begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008601','reward-parent@example.invalid'),('00000000-0000-4000-8000-000000008602','reward-other@example.invalid');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008601','Synthetic','00000000-0000-4000-8000-000000008601'),('10000000-0000-4000-8000-000000008602','Other','00000000-0000-4000-8000-000000008602');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008601','00000000-0000-4000-8000-000000008601'),('10000000-0000-4000-8000-000000008602','00000000-0000-4000-8000-000000008602');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008601','10000000-0000-4000-8000-000000008601','Ece',5),('20000000-0000-4000-8000-000000008602','10000000-0000-4000-8000-000000008602','Other child',5);
insert into public.family_rewards(id,family_id,title,icon,cost_stars) values('30000000-0000-4000-8000-000000008601','10000000-0000-4000-8000-000000008601','Sinema','reward-movie-night',20),('30000000-0000-4000-8000-000000008602','10000000-0000-4000-8000-000000008601','Kitap','reward-book',30);
insert into public.star_events(family_id,child_id,delta,reason) values('10000000-0000-4000-8000-000000008601','20000000-0000-4000-8000-000000008601',100,'adjust');
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008603','reward-device@example.invalid');
insert into public.devices(id,family_id,auth_user_id,active_child_id) values('60000000-0000-4000-8000-000000008603','10000000-0000-4000-8000-000000008601','00000000-0000-4000-8000-000000008603','20000000-0000-4000-8000-000000008601');
create function pg_temp.r() returns uuid language sql as $$select '30000000-0000-4000-8000-000000008601'::uuid$$;
create function pg_temp.ch() returns uuid language sql as $$select '20000000-0000-4000-8000-000000008601'::uuid$$;
create function pg_temp.q() returns uuid language sql as $$select id from public.reward_requests where idempotency_key='40000000-0000-4000-8000-000000008601'$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008601","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008601","role":"parent"}}',true);
select lives_ok($$select public.request_reward(pg_temp.r(),'40000000-0000-4000-8000-000000008601',pg_temp.ch())$$,'request created');
select is((select reward_snapshot->>'title' from public.reward_requests where id=pg_temp.q()),'Sinema','request freezes title');
select is((public.change_reward('50000000-0000-4000-8000-000000008601',pg_temp.r(),1,'save','{"title":"Ailece sinema","cost_stars":40}')->>'revision')::int,2,'edit increments revision');
select is((public.change_reward('50000000-0000-4000-8000-000000008601',pg_temp.r(),1,'save','{"title":"Ailece sinema","cost_stars":40}')->>'revision')::int,2,'lost reply replays same revision');
select is(jsonb_array_length(public.reward_history(pg_temp.r())->'rows'),2,'retry creates no extra history');
select is((select reward_snapshot->>'title' from public.reward_requests where id=pg_temp.q()),'Sinema','edit preserves original name');
select is((select cost_snapshot::int from public.reward_requests where id=pg_temp.q()),20,'edit preserves original price');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),1,'pause')$$,'P0001','reward_changed','stale revision blocked');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),2,'save','{"title":"X","cost_stars":501}')$$,'P0001','reward_invalid','price range');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),2,'save','{"title":"X","cost_stars":1.5}')$$,'P0001','reward_invalid','no fractional stars');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),2,'save','{"title":"X","cost_stars":20,"family_id":"x"}')$$,'P0001','reward_invalid','unknown fields blocked');
select throws_ok($$update public.family_rewards set title='Bypass' where id=pg_temp.r()$$,'42501',null,'direct edit forbidden');
select throws_ok($$delete from public.family_rewards where id=pg_temp.r()$$,'42501',null,'direct destructive delete forbidden');
select lives_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),2,'archive')$$,'archive preserves pending request');
select is((public.reward_history(pg_temp.r())->>'pending')::int,1,'pending visible in impact');
select lives_ok($$select public.request_reward(pg_temp.r(),'40000000-0000-4000-8000-000000008601',pg_temp.ch())$$,'retry even after catalogue archive');
select throws_ok($$select public.request_reward(pg_temp.r(),gen_random_uuid(),pg_temp.ch())$$,'P0001','reward_not_found','new request blocked');
select lives_ok($$select public.decide_reward_request(pg_temp.q(),true)$$,'old request approval remains possible');
select is((select delta from public.star_events where reward_request_id=pg_temp.q()),-20,'original price debited');
select lives_ok($$select public.decide_reward_request(pg_temp.q(),true)$$,'approval retry safe');
select is((select count(*)::int from public.star_events where reward_request_id=pg_temp.q()),1,'one debit');
select is((select reward_snapshot->>'title' from public.reward_requests q join public.child_inventory i on i.request_id=q.id where q.id=pg_temp.q()),'Sinema','inventory references original identity');
select lives_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),3,'restore')$$,'restore');
select is((select active from public.family_rewards where id=pg_temp.r()),false,'restore paused');
select lives_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),4,'resume')$$,'resume explicit');
select lives_ok($$select public.set_child_goal(pg_temp.r(),pg_temp.ch())$$,'choose goal');
select is(jsonb_array_length(public.reward_history(pg_temp.r())->'goals'),1,'preview names affected child');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),5,'save','{"title":"X","cost_stars":90}')$$,'P0001','reward_has_goals','goal cannot unexpectedly move');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),5,'archive')$$,'P0001','reward_has_goals','cannot orphan active goal');
select lives_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),5,'pause')$$,'pause permitted without erasing goal');
select is((select count(*)::int from public.child_goals where reward_id=pg_temp.r() and status='active'),1,'pause preserves goal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008603","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008601","role":"device","device_id":"60000000-0000-4000-8000-000000008603","child_id":"20000000-0000-4000-8000-000000008601"}}',true);
select is((select title from public.family_rewards where id=pg_temp.r()),'Ailece sinema','paired child still sees paused goal identity');
select is((select count(*)::int from public.reward_catalog_sync),1,'paired child can receive family catalogue signal');
select throws_ok($$select public.reward_history(pg_temp.r())$$,'42501','forbidden','real paired child cannot read edit history');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),6,'resume')$$,'42501','forbidden','real paired child cannot alter reward');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008601","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008601","role":"parent"}}',true);

select lives_ok($$select public.set_child_goal('30000000-0000-4000-8000-000000008602',pg_temp.ch())$$,'parent explicitly chooses another goal');
select lives_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),6,'archive')$$,'archive after explicit goal replacement');
select is(public.reward_history(pg_temp.r(),6)->'rows'->0->>'action','resume','cursor pagination');
select throws_ok($$select public.request_reward('30000000-0000-4000-8000-000000008602','40000000-0000-4000-8000-000000008601',pg_temp.ch())$$,'P0001','request_conflict','request key cannot switch reward');
select throws_ok($$select public.request_reward('30000000-0000-4000-8000-000000008602',gen_random_uuid(),'20000000-0000-4000-8000-000000008602')$$,'42501','child_not_found','foreign child rejected before write');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008602","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008602","role":"parent"}}',true);
select throws_ok($$select public.reward_history(pg_temp.r())$$,'42501','forbidden','other family cannot read history');
select is((select count(*)::int from public.reward_catalog_sync where family_id='10000000-0000-4000-8000-000000008601'),0,'other family cannot observe catalogue signals');
select throws_ok($$select public.change_reward(gen_random_uuid(),pg_temp.r(),7,'restore')$$,'42501','forbidden','other family cannot edit');
select throws_ok($$select public.request_reward(pg_temp.r(),'40000000-0000-4000-8000-000000008601','20000000-0000-4000-8000-000000008602')$$,'P0001','request_conflict','known receipt cannot leak another family response');
select set_config('request.jwt.claims','{"role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000008601","role":"device","child_id":"20000000-0000-4000-8000-000000008601"}}',true);
select throws_ok($$select public.reward_history(pg_temp.r())$$,'42501','forbidden','child cannot read parent history');
reset role;
select ok(not has_function_privilege('anon','public.change_reward(uuid,uuid,integer,text,jsonb)','execute'),'anonymous denied');
select ok(not has_table_privilege('authenticated','gina.reward_changes','select'),'private history table');
select ok(not has_table_privilege('authenticated','public.reward_catalog_sync','update'),'clients cannot forge catalogue signals');
select * from finish();rollback;
